import{_ as e,o as i,c as a,a5 as t}from"./chunks/framework.BPFk9-tb.js";const d=JSON.parse('{"title":"写作课作业-000","description":"","frontmatter":{"date":"2020-08-11T20:00:19","title":"写作课作业-000","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[{"level":2,"title":"写作课作业1","slug":"写作课作业1","link":"#写作课作业1","children":[]},{"level":2,"title":"写作课作业2","slug":"写作课作业2","link":"#写作课作业2","children":[]},{"level":2,"title":"写作课作业3","slug":"写作课作业3","link":"#写作课作业3","children":[]},{"level":2,"title":"写作课作业4","slug":"写作课作业4","link":"#写作课作业4","children":[]},{"level":2,"title":"写作课作业5","slug":"写作课作业5","link":"#写作课作业5","children":[]},{"level":2,"title":"写作课作业5","slug":"写作课作业5-1","link":"#写作课作业5-1","children":[]},{"level":2,"title":"写作课作业6","slug":"写作课作业6","link":"#写作课作业6","children":[]},{"level":2,"title":"写作课作业7","slug":"写作课作业7","link":"#写作课作业7","children":[]}],"relativePath":"posts/homework/000.md","filePath":"posts/homework/000.md"}'),o={name:"posts/homework/000.md"};function r(u,l,n,p,c,h){return i(),a("div",null,[...l[0]||(l[0]=[t('<h2 id="写作课作业1" tabindex="-1">写作课作业1 <a class="header-anchor" href="#写作课作业1" aria-label="Permalink to &quot;写作课作业1&quot;">​</a></h2><blockquote><ul><li>每天看文章：圈出名词和画出形容词，感知作者的感知，学习钻进作者的脑子。</li><li>读任何文章都要问三个问题： <ul><li>作者想要向我传递什么样的感知？</li><li>作者做得成功吗？</li><li>如果我是他，怎么做更加有效？</li></ul></li><li>每天用300-500字描述一个特点的感知：视觉、听觉、味觉和触觉；遇到的人和事；喜怒哀乐等情绪，认真思考自己传递的感知有效吗？</li></ul></blockquote><h2 id="写作课作业2" tabindex="-1">写作课作业2 <a class="header-anchor" href="#写作课作业2" aria-label="Permalink to &quot;写作课作业2&quot;">​</a></h2><blockquote><ul><li>你遇到过的最好教程？</li><li>你需要的教程别人写得好不好？</li><li>如果你自己写，你能写成什么样？</li><li>开始动手写100篇教程……</li><li>不停搜集反馈……反复揣摩……</li></ul></blockquote><h2 id="写作课作业3" tabindex="-1">写作课作业3 <a class="header-anchor" href="#写作课作业3" aria-label="Permalink to &quot;写作课作业3&quot;">​</a></h2><blockquote><ul><li>给孩子讲清楚教科书的结构</li><li>分析文章，2W1H</li><li>分析书籍，2W1H</li></ul></blockquote><h2 id="写作课作业4" tabindex="-1">写作课作业4 <a class="header-anchor" href="#写作课作业4" aria-label="Permalink to &quot;写作课作业4&quot;">​</a></h2><blockquote><ul><li><p>《把时间当作朋友》第一版，第三版对照着看，不断的寻找并列，递进，转折的逻辑关系，看看元素是如何排列的，他是怎么做到的？</p></li><li><p>《定投改变命运》第一版，第二版，第三版对照着看，不断的寻找并列，递进，转折的逻辑关系，看看元素是如何排列的，想想看为了这样排列需要花怎样的功夫才能找到这些东西。</p></li><li><p>看到李笑来的进步过程，不是从一开始就像现在这样，更不是生来就是如此，他也是一点一点进步，一点一点积累，一点一点改善，花了很久很久才走到现在这个地方，更重要的是他和所有人一样还好接着往前走。</p></li><li><p>分析更多的你喜欢的创作者的内容，看看他们是怎么设计自己的内容之内的各种元素排列的，猜想一下他们是如何做到的，再略微琢磨下你自己如何才能做到像他们一样。</p></li></ul></blockquote><h2 id="写作课作业5" tabindex="-1">写作课作业5 <a class="header-anchor" href="#写作课作业5" aria-label="Permalink to &quot;写作课作业5&quot;">​</a></h2><blockquote><ul><li><p>买一本《围城》，把书里的所有类比都找出来，一个一个的去理解一遍，一个一个的去揣摩一遍，一个一个的去想人家是怎么想到这个的类比，它为什么精彩。</p></li><li><p>至少读一遍《定投改变命运》，把书里的所有类比都找出来，一个一个的去理解一遍，作者是怎么找到这个类比的，或者是从哪里收集到这个类比的。</p></li><li><p>《自己的笔记本》，从今天开始遇到任何类比都要收集到一起，放到那里，你这样想就对了，每个精彩的类比都是一笔极大的财富。</p></li></ul></blockquote><h2 id="写作课作业5-1" tabindex="-1">写作课作业5 <a class="header-anchor" href="#写作课作业5-1" aria-label="Permalink to &quot;写作课作业5&quot;">​</a></h2><blockquote><ul><li><p>建立每天写至少1千字的习惯</p></li><li><p>建立每天阅读至少2万字的习惯</p></li><li><p>每天都要琢磨人家的输出来自于怎么样的输入？</p></li><li><p>抽时间认真阅读精彩电影的影评，琢磨一下为什么人家看到的东西你却竟然完全没有看到？</p></li></ul></blockquote><h2 id="写作课作业6" tabindex="-1">写作课作业6 <a class="header-anchor" href="#写作课作业6" aria-label="Permalink to &quot;写作课作业6&quot;">​</a></h2><blockquote><p>精读以下三位作者的三本书：丹•布朗《达芬奇密码》、贾雷德•戴蒙德《枪炮、病毒与钢铁》和托马斯•索威尔《美国种族简史》，体会和思考三位作者什么叫专业。</p></blockquote><h2 id="写作课作业7" tabindex="-1">写作课作业7 <a class="header-anchor" href="#写作课作业7" aria-label="Permalink to &quot;写作课作业7&quot;">​</a></h2><blockquote><p>买一个本子，每天记录和反思自己的沟通是否有效（2年左右），可以改变命运的本子。</p><p>拿出一张白纸，在顶部写一句你自己想说的话，然后在下面尽可能多的写出能表达同样意思的句子， 穷尽多种可能性。</p><p>每天反复梳理自己的价值观：</p><p>你认为什么是对的，什么是错的；什么对你来说是无所谓的，什么对你来说是大是大非的。</p><p>你认为什么更重要，什么最重要？有没有什么事情重要到若是没有它，你甚至活着没劲？</p><p>这事儿对吗？<br> 什么更重要？</p><p>什么最重要？</p><p>什么事绝对不能做？</p><p>什么事一定要做到底？</p></blockquote>',16)])])}const k=e(o,[["render",r]]);export{d as __pageData,k as default};
